<template>
    <div>
        <Head title="Extended Tables" />

        <Card title="Simple Table" icon="assignment" card-header-class="card-header-rose">
            <div class="table-responsive">
                <table class="table">
                    <caption class="visually-hidden">Employee table with row actions</caption>
                    <thead>
                        <tr>
                            <th scope="col" class="text-center">#</th>
                            <th scope="col">Name</th>
                            <th scope="col">Job Position</th>
                            <th scope="col">Since</th>
                            <th scope="col" class="text-end">Salary</th>
                            <th scope="col" class="text-end">Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr v-for="employee in employees" :key="employee.id">
                            <td class="text-center">{{ employee.id }}</td>
                            <td>{{ employee.name }}</td>
                            <td>{{ employee.position }}</td>
                            <td>{{ employee.since }}</td>
                            <td class="text-end text-nowrap">€ {{ formatNumber(employee.salary) }}</td>
                            <td class="text-end td-actions">
                                <div class="d-flex justify-content-end gap-1">
                                    <button
                                        v-for="action in employeeActions"
                                        :key="action.key"
                                        v-tippy="action.label"
                                        type="button"
                                        class="btn"
                                        :class="[action.color, employee.buttonStyle]"
                                        :aria-label="`${action.label}: ${employee.name}`"
                                        @click="handleEmployeeAction(action.key, employee)"
                                    >
                                        <i class="material-icons" aria-hidden="true">{{ action.icon }}</i>
                                    </button>
                                </div>
                            </td>
                        </tr>
                        <tr v-if="!employees.length"><td colspan="6" class="text-center">No employees remaining.</td></tr>
                    </tbody>
                </table>
            </div>
        </Card>

        <Card title="Striped Table" icon="assignment" card-header-class="card-header-rose">
            <div class="table-responsive">
                <table class="table table-striped">
                    <caption class="visually-hidden">Product table with selection checkboxes</caption>
                    <thead>
                        <tr>
                            <th scope="col" class="text-center">#</th>
                            <th scope="col"><span class="visually-hidden">Selection</span></th>
                            <th scope="col">Product Name</th>
                            <th scope="col">Type</th>
                            <th scope="col">Qty</th>
                            <th scope="col" class="text-end">Price</th>
                            <th scope="col" class="text-end">Amount</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr v-for="product in products" :key="product.id">
                            <td class="text-center">{{ product.id }}</td>
                            <td><Checkbox v-model:checked="checkedProducts" :value="product.id" :aria-label="`Select ${product.name}`" /></td>
                            <td>{{ product.name }}</td>
                            <td>{{ product.type }}</td>
                            <td>{{ product.quantity }}</td>
                            <td class="text-end text-nowrap">€ {{ product.price }}</td>
                            <td class="text-end text-nowrap">€ {{ product.amount }}</td>
                        </tr>
                    </tbody>
                    <tfoot>
                        <tr>
                            <th colspan="6" scope="row" class="td-total text-end">Total</th>
                            <td class="td-price text-nowrap">€ 12,999</td>
                        </tr>
                    </tfoot>
                </table>
            </div>
        </Card>

        <Card title="Shopping Cart Table" icon="assignment" card-header-class="card-header-rose">
            <div class="table-responsive">
                <table class="table table-shopping">
                    <caption class="visually-hidden">Shopping cart with quantity controls</caption>
                    <thead>
                        <tr>
                            <th scope="col"><span class="visually-hidden">Image</span></th>
                            <th scope="col">Product</th>
                            <th scope="col" class="th-description">Color</th>
                            <th scope="col" class="th-description">Size</th>
                            <th scope="col" class="text-end">Price</th>
                            <th scope="col" class="text-end">Qty</th>
                            <th scope="col" class="text-end">Amount</th>
                            <th scope="col"><span class="visually-hidden">Actions</span></th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr v-for="item in cart" :key="item.id">
                            <td><div class="img-container"><img :src="item.image" alt="" /></div></td>
                            <td class="td-name">{{ item.name }}<br /><small>by {{ item.brand }}</small></td>
                            <td>{{ item.color }}</td>
                            <td>{{ item.size }}</td>
                            <td class="td-number text-nowrap"><small>€</small>{{ formatNumber(item.price) }}</td>
                            <td class="td-number text-nowrap">
                                {{ item.quantity }}
                                <div class="btn-group btn-group-sm" role="group" :aria-label="`${item.name} quantity`">
                                    <button type="button" class="btn btn-round btn-info" aria-label="Decrease quantity" :disabled="item.quantity === 1" @click="item.quantity--">
                                        <i class="material-icons" aria-hidden="true">remove</i>
                                    </button>
                                    <button type="button" class="btn btn-round btn-info" aria-label="Increase quantity" @click="item.quantity++">
                                        <i class="material-icons" aria-hidden="true">add</i>
                                    </button>
                                </div>
                            </td>
                            <td class="td-number text-nowrap"><small>€</small>{{ formatNumber(item.price * item.quantity) }}</td>
                            <td class="td-actions">
                                <button v-tippy="'Remove item'" type="button" class="btn btn-link" :aria-label="`Remove ${item.name}`" @click="cart = cart.filter((product) => product.id !== item.id)">
                                    <i class="material-icons" aria-hidden="true">close</i>
                                </button>
                            </td>
                        </tr>
                        <tr v-if="!cart.length"><td colspan="8" class="text-center">The demo cart is empty.</td></tr>
                    </tbody>
                    <tfoot>
                        <tr>
                            <th colspan="6" scope="row" class="td-total text-end">Total</th>
                            <td class="td-price text-nowrap"><small>€</small>{{ formatNumber(cartTotal) }}</td>
                            <td></td>
                        </tr>
                        <tr>
                            <td colspan="8" class="text-end">
                                <button type="button" class="btn btn-info btn-round" :disabled="!cart.length" @click="$refs.purchase.show()">
                                    Complete Purchase <i class="material-icons" aria-hidden="true">keyboard_arrow_right</i>
                                </button>
                            </td>
                        </tr>
                    </tfoot>
                </table>
            </div>
        </Card>

        <Modal ref="employee" :title="editing ? 'Edit employee' : 'Employee details'">
            <form v-if="employeeDraft" id="extended-table-employee" @submit.prevent="saveEmployee">
                <TextInputGroup name="extended-employee-name" label="Name" v-model="employeeDraft.name" :disabled="!editing" />
                <TextInputGroup name="extended-employee-position" label="Job Position" v-model="employeeDraft.position" :disabled="!editing" />
                <p v-if="!editing" class="mt-3 mb-0">Since {{ employeeDraft.since }} · € {{ formatNumber(employeeDraft.salary) }}</p>
            </form>
            <template v-if="editing" #footer>
                <button type="submit" form="extended-table-employee" class="btn btn-rose" :disabled="!employeeDraft?.name.trim() || !employeeDraft?.position.trim()">Save</button>
            </template>
        </Modal>

        <Modal ref="purchase" title="Demo purchase">
            <p class="mb-0">Order total: € {{ formatNumber(cartTotal) }}. No payment is taken in this demo.</p>
        </Modal>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';
import Checkbox from '@scaffold/components/Checkbox.vue';
import Modal from '@scaffold/components/Modal.vue';
import TextInputGroup from '@scaffold/components/TextInputGroup.vue';
import jacket from '@scaffold-assets/product-1.jpg';
import pants from '@scaffold-assets/product-2.jpg';
import skirt from '@scaffold-assets/product-3.jpg';

export default {
    name: 'ExtendedTablesDemo',
    components: { Card, Checkbox, Head, Modal, TextInputGroup },
    layout: { pageTitle: 'Extended Tables' },
    data() {
        return {
            employees: [
                { id: 1, name: 'Andrew Mike', position: 'Develop', since: 2013, salary: 99225 },
                { id: 2, name: 'John Doe', position: 'Design', since: 2012, salary: 89241, buttonStyle: 'btn-round' },
                { id: 3, name: 'Alex Mike', position: 'Design', since: 2010, salary: 92144, buttonStyle: 'btn-link' },
                { id: 4, name: 'Mike Monday', position: 'Marketing', since: 2013, salary: 49990, buttonStyle: 'btn-round' },
                { id: 5, name: 'Paul Dickens', position: 'Communication', since: 2015, salary: 69201 },
            ],
            employeeActions: [
                { key: 'view', label: 'View', icon: 'person', color: 'btn-info' },
                { key: 'edit', label: 'Edit', icon: 'edit', color: 'btn-success' },
                { key: 'remove', label: 'Remove', icon: 'close', color: 'btn-danger' },
            ],
            employeeDraft: null,
            editing: false,
            checkedProducts: [1, 2, 3],
            products: [
                { id: 1, name: 'Moleskine Agenda', type: 'Office', quantity: 25, price: '49', amount: '1,225' },
                { id: 2, name: 'Stabilo Pen', type: 'Office', quantity: 30, price: '10', amount: '300' },
                { id: 3, name: 'A4 Paper Pack', type: 'Office', quantity: 50, price: '10.99', amount: '109' },
                { id: 4, name: 'Apple iPad', type: 'Meeting', quantity: 10, price: '499.00', amount: '4,990' },
                { id: 5, name: 'Apple iPhone', type: 'Communication', quantity: 10, price: '599.00', amount: '5,999' },
            ],
            cart: [
                { id: 1, name: 'Spring Jacket', brand: 'Dolce&Gabbana', color: 'Red', size: 'M', price: 549, quantity: 1, image: jacket },
                { id: 2, name: 'Short Pants', brand: 'Pucci', color: 'Purple', size: 'M', price: 499, quantity: 2, image: pants },
                { id: 3, name: 'Pencil Skirt', brand: 'Valentino', color: 'White', size: 'XL', price: 799, quantity: 1, image: skirt },
            ],
        };
    },
    computed: {
        cartTotal() {
            return this.cart.reduce((total, item) => total + item.price * item.quantity, 0);
        },
    },
    methods: {
        formatNumber(value) {
            return value.toLocaleString('en-US');
        },
        handleEmployeeAction(action, employee) {
            if (action === 'remove') {
                this.employees = this.employees.filter((row) => row.id !== employee.id);
                return;
            }
            this.editing = action === 'edit';
            this.employeeDraft = { ...employee };
            this.$refs.employee.show();
        },
        saveEmployee() {
            const name = this.employeeDraft.name.trim();
            const position = this.employeeDraft.position.trim();
            if (!name || !position) {
                return;
            }
            const employee = this.employees.find((row) => row.id === this.employeeDraft.id);
            Object.assign(employee, { name, position });
            this.$refs.employee.hide();
        },
    },
};
</script>
